<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\TemplateVariable\Domain\ValueObject;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFail;

class TemplateVariableEnabledVO
{
    public static function empty(): TemplateVariableEnabledVO
    {
        return new TemplateVariableEnabledVO(null);
    }
    public static function from(TemplateVariableEnabledVO|bool|null $value): TemplateVariableEnabledVO
    {
        return self::fromUnsafe($value);
    }
    public static function tryFrom(mixed $value, ConstraintFailList $list): ?TemplateVariableEnabledVO
    {
        if ($value instanceof TemplateVariableEnabledVO) {
            // If is a ValueObject, its already validated... nothing to append
            return $value;
        } elseif (!$value) {
            return new TemplateVariableEnabledVO($value);
        } elseif (is_bool($value)) {
            return new TemplateVariableEnabledVO($value);
        } else {
            $list->add(new ConstraintFail('wrong_type', ['enabled'], [$value], ['bool']));
            return null;
        }
    }
    private static function fromUnsafe(mixed $value): TemplateVariableEnabledVO
    {
        if ($value instanceof TemplateVariableEnabledVO) {
            // If is a ValueObject, its already validated
            return $value;
        } else {
            // If is not a ValueObject, validation is need and exception throw
            $errorsList = new ConstraintFailList();
            $candidate = self::tryFrom($value, $errorsList);
            if ($errorsList->hasErrors()) {
                throw $errorsList->asConstraintException();
            }
            \assert($candidate instanceof TemplateVariableEnabledVO);
            return $candidate;
        }
    }
    /**
     * private constructor to avoid build a value without all the rule validations.
     */
    private function __construct(
        private readonly ?bool $enabled
    ) {
    }
    public function value(): ?bool
    {
        return $this->enabled;
    }
    public function equals(?TemplateVariableEnabledVO $other): bool
    {
        return $this->value() == $other?->value();
    }
}
